pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }
    function testRegression_property() public {
        address from = address(0x1);
        address caddress = address(0x2);
        address[] memory emptyTos = new address[](0);
        uint v = 100;

        bool ok;
        try c.transfer(from, caddress, emptyTos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "reference should revert on empty _tos");
    }
}
